// seed defaults on deploy
const PMS_BASE = 'http://192.168.1.116:8010';
const MACHINE_ID = 8;
const DEVICE_NAME = 'SPM_AH_PLC';
flow.set('pmsBase', String(PMS_BASE).replace(/\/$/, ''));
flow.set('machineId', MACHINE_ID);
