const d = msg.payload;
msg.payload = {
    timestamp:     new Date().toISOString(),
    pressure:      d[0],
    flow:          d[2],
    tankLevel:     d[4],
    temperature:   d[6],
    plcStatus:     d[12] // 2 --> PLC B and 1 --> PLC A Master
};
flow.set('plcdata', msg.payload);
return msg;

const d = msg.payload;
msg.payload = {
    timestamp: new Date().toISOString(),
    // Digital Output Status - Output register M301-M308
    Pump    : d[0],//M301
    Blower  : d[1],//M302
    Chiller : d[2],//M303
    Motor   : d[3],//M304
    Boiler  : d[4],//M305
    Furnace : d[5],//M306
    Conveyor: d[6],//M307
    Electric_Generators: d[7],//M308
    // Digital Input Status - Input register M309 - M316
    Digital_Input1: d[8],//M309
    Digital_Input2: d[9],//M310
    Digital_Input3: d[10],//M311
    Digital_Input4: d[11],//M312
    Digital_Input5: d[12],//M313
    Digital_Input6: d[13],//M314
    Digital_Input7: d[14],//M315
    Digital_Input8: d[15]//M316
};
flow.set('coils', msg.payload);
return msg;

const plc = flow.get('plcdata');
const coils = flow.get('coils');
if (!plc || !coils) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'waiting plc+coils' });
    return null;
}

const pmsBase = flow.get('pmsBase') || 'http://192.168.1.116:8010';
const machineId = flow.get('machineId') || 8;
const deviceName = flow.get('deviceName') || 'SPM_AH_PLC';

function reading(name, value) {
    return { name, value: value === undefined || value === null ? null : value };
}

const readings = [
    reading('pressure', plc.pressure),
    reading('flow', plc.flow),
    reading('tankLevel', plc.tankLevel),
    reading('temperature', plc.temperature),
    reading('plcStatus', plc.plcStatus),
    reading('Pump', coils.Pump),
    reading('Blower', coils.Blower),
    reading('Chiller', coils.Chiller),
    reading('Motor', coils.Motor),
    reading('Boiler', coils.Boiler),
    reading('Furnace', coils.Furnace),
    reading('Conveyor', coils.Conveyor),
    reading('Electric_Generators', coils.Electric_Generators),
    reading('Digital_Input1', coils.Digital_Input1),
    reading('Digital_Input2', coils.Digital_Input2),
    reading('Digital_Input3', coils.Digital_Input3),
    reading('Digital_Input4', coils.Digital_Input4),
    reading('Digital_Input5', coils.Digital_Input5),
    reading('Digital_Input6', coils.Digital_Input6),
    reading('Digital_Input7', coils.Digital_Input7),
    reading('Digital_Input8', coils.Digital_Input8)
];

msg.url = pmsBase + '/api/machines/' + machineId + '/telemetry';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    syncBy: 'MODBUS',
    origin: Date.now(),
    deviceName: deviceName,
    machine_id: machineId,
    readings: readings
};
node.status({ fill: 'blue', shape: 'dot', text: 'posting' });
return msg;

const code = msg.statusCode || 0;
if (code >= 200 && code < 300) {
    node.status({ fill: 'green', shape: 'dot', text: 'ok ' + code });
} else {
    node.status({ fill: 'red', shape: 'ring', text: 'fail ' + code });
}
return msg;

const plc = flow.get('plcdata') || {};
const coils = flow.get('coils') || {};
msg.payload = Object.keys(plc).length || Object.keys(coils).length
    ? { ...plc, ...coils }
    : { error: 'No data yet' };
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': 'http://192.168.1.116:5174',
    'Access-Control-Allow-Methods': 'GET',
    'Access-Control-Allow-Headers': 'Content-Type'
};
return msg;
